&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;FSA, HSA, and dependent care&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; accounts.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;401(k) &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;with 3% non-elective contribution.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexible PTO&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; to take time when you need it.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Join a team that values your work, supports your growth, and invests in your future!&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We offer a competitive salary range of $80,000–$110,000&amp;nbsp;for&amp;nbsp;the Energy Analyst role and $100,000–$140,000 for Senior Analyst. Compensation is flexible and will be tailored to your experience and background —&amp;nbsp;we&#39;re&amp;nbsp;proud to offer pay that is often above industry average. But the&amp;nbsp;perks&amp;nbsp;don’t&amp;nbsp;stop there —&amp;nbsp;we’re&amp;nbsp;committed to creating a workplace where people can do meaningful work, grow their careers, and still have a life outside the office.&amp;nbsp;You’ll&amp;nbsp;enjoy flexible work hours, a collaborative environment, and real opportunities for advancement.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Collaboration is in our DNA, and we thrive on the energy of working together — the spontaneous ideas, face-to-face teamwork, and culture you can only build in a room.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;But we also value the focus and freedom that remote flexibility brings.&amp;nbsp;That&#39;s&amp;nbsp;why our Boulder, CO office runs on a hybrid schedule (3 days in-office, 2 days remote).&amp;nbsp;We prefer&amp;nbsp;candidates&amp;nbsp;who can work from Boulder HQ, though&amp;nbsp;we&#39;re&amp;nbsp;open to strong remote candidates as well.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Need&amp;nbsp;accommodations?&amp;nbsp;Contact us at&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;a href=&quot;mailto:recruiting@ascendanalytics.com&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;recruiting@ascendanalytics.com&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/a&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ascend Analytics is an Equal Employment Opportunity employer. We celebrate diversity and are committed to an inclusive environment for all employees regardless of race, religion, color, national origin, sex, sexual orientation, gender identity or expression, age, veteran status, disability, or genetic information.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Note: &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We regret that we are currently unable to offer visa sponsorship.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

